def subtract(a, b):
    # Filter out empty intervals and normalize
    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    if not a_intervals:
        return []

    # Merge overlapping intervals in a
    a_sorted = sorted(a_intervals)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_sorted = sorted(b_intervals)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = a_start

        for b_start, b_end in b_merged:
            if b_end <= current:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after a interval
                break

            if b_start > current:
                # Add the gap before b interval
                result.append([current, b_start])

            # Move current past the b interval
            current = max(current, b_end)

        if current < a_end:
            # Add remaining part of a interval
            result.append([current, a_end])

    return result

